  p=read(jd/'packet.actual.json');reply=read(jd/'reply.json');prior=read(pd/'reply.json');assert p['priorReview']==prior;assert read(jd/'receipt.json')['inputPins']['dependency']['priorReceiptSha256']==sha(pd/'receipt.json');assert read(jd/'receipt.json')['inputPins']['dependency']['priorReplySha256']==sha(pd/'reply.json')
